    "desc": "שמן קוקוס בתולי אורגני שמופק בכבישה קרה מפרי הקוקוס הטרי, ושומר על טעם וארומה מובהקים (לחובבי הז'אנר). אידיאלי לאפייה מתוקה שטעם קוקוסי מחמיא לה, לקארי תאילנדי ואפילו יכול לשמש למריחה חיצונית על העור. \nחשוב לזכור כי בשל נקודת העשן הנמוכה יותר של שמן בתולי וטעמו הדומיננטי, הוא אינו מתאים לטיגון עמוק בטמפרטורות גבוהות או למנות שבהן מעוניינים בפרופיל טעמים ניטרלי. \n\n",
