    "conf": "בינונית",
    "brand": "Coconut Secret",
    "longDesc": "Coconut Aminos הוא רוטב תיבול שעשוי ממוהל פריחת קוקוס ומלח. למרות השם, הוא בדרך כלל לא טועם 'קוקוסי'; הפרופיל מלוח־מתקתק ועדין יותר מסויה.\n\nהקסם כאן נמצא ב רוטב אמינו מקוקוס, תחליף רוטב סויה, מעט מתוק ועדין. אמינו קוקוס הוא תחליף עדין ומתוק יותר לרוטב סויה, ובדרך כלל אין לו טעם קוקוס בולט. כמה טיפות או כפיות יכולות לשדרג אורז, ביצים, ירקות או מרק. הוא מוסיף מליחות ואומאמי בדרך ישירה, ולכן מעט ממנו יכול להספיק.\n\nכדאי לדעת: לעומת רוטב סויה או טמארי הוא פחות מלוח ופחות עמוק באומאמי, אבל מעט מתוק יותר. לכן הוא שימושי למי שנמנע מסויה, אך לא תמיד נותן אותה עוצמה במנות אסייתיות.\n\nטיפים לשימוש:\n• למוקפץ של שתי מנות: להתחיל בכף וחצי ולהוסיף מלח רק אחרי טעימה\n• למרינדה ל־300 גרם טופו: 2 כפות Coconut Aminos + ג'ינג'ר + שום\n• לרוטב בוטנים: כף Coconut Aminos + 2 כפות חמאת בוטנים + ליים + מים\n• לגלייז לסלמון: 2 כפות + כפית דבש/מייפל, לצמצם קלות ולהבריש",
    "descNew": "אמינו קוקוס, תחליף לרוטב סויה שמופק מלשד פרחי דקל הקוקוס עם מלח ים. מתוק־מלוח באיזון ייחודי, ללא סויה, ללא גלוטן ובעל תכולת נתרן נמוכה משמעותית. Coconut Secret היא חלוצת מוצרי הקוקוס האלטרנטיביים לסויה ולסוכר.",
