    "desc": "מיסו שירו הוא למעשה מיסו בהיר, והוא מהווה את הגרסה המעודנת והקלילה ביותר של המשחה היפנית. המיסו של Eden Foods מיוצר ביפן בשיטה מסורתית של תסיסה טבעית של אורז וסויה למשך 60 יום לפחות, עם יחס אורז גבוה שמעניק מתיקות עדינה ומליחות נמוך יחסית לחלופות דומות שניתן להשיג בישראל. הטעם המאוזן מוסיף עומק נהדר למרקים, מרינדות, ירקות קלויים, רטבים לסלט ואפילו לקינוחים. מתאים במיוחד למי שממילא מזמין ב-iHerb וחוסך משלוח נפרד. את המיסו שומרים במקום קריר ואפל בארון עד הפתיחה, ולאחר מכן מעבירים למקרר – שם המיסו יישמר מצוין לאורך חודשים.\n",
