    "longDesc": "Shiro Miso של Eden הוא מיסו בהיר מסויה ואורז לבן שעובר תסיסה קצרה יחסית, כ־2 חודשים. התסיסה הקצרה מסבירה את הצבע הבהיר, הקרמיות והטעם המתוק־מלוח העדין שלו.\n\nמיסו שירו (לבן) אורגני של Eden Foods, מותסס 60 יום בשיטה יפנית מסורתית. מה שמייחד אותו: יחס אורז גבוה במיוחד (כ-39%) ביחס לסויה, מה שנותן לו פרופיל טעם עדין, מעט מתוק, ופחות מלוח ממיסו שירו מקומי. בהשוואה למוצרים הנמכרים בישראל, מיסו שירו מסחרי מקומי מכיל לרוב הרבה יותר נתרן ויחס סויה גבוה יותר, מה שנותן טעם חזק ומלוח יותר.\n\nמתאים בהחלט למרק מיסו עדין, לרטבי סלט, מרינדות לדגים ועוף, ורטבים לפסטה. מי שרגיל למיסו מהסופר עשוי להיות מופתע מהעדינות שלו.\n\nהערה: מי שמזמין ממילא מ-iHerb ומחפש מיסו שירו, זה בחירה טובה. כחלופה מקומית, Fine Japan Organic Shiro Miso (עם הכשר OK) מציע פרופיל טעם דומה.\n\nכדאי לדעת: לעומת Genmai Miso של Eden, שמתיישן כ־10 חודשים עם אורז חום, Shiro עדין ומתוק יותר ופחות מלוח. הוא מתאים במיוחד לרטבים, גלייזים, ממרחים וקינוחים שבהם רוצים אומאמי בלי טעם מותסס עמוק.\n\nטיפים לשימוש:\n• לרוטב סלט: לטרוף כף שירו מיסו + כף טחינה + כף לימון + 2–3 כפות מים\n• לגלייז ל־2 פילטי סלמון: כף מיסו + כף מייפל + כפית חומץ אורז, למרוח ולצלות\n• למרק: להמיס 1–1.5 כפיות בכוס מרק חם לאחר שמנמיכים את האש\n• לעוגיות או קרמל: כפית אחת מספיקה להוסיף מליחות ואומאמי בלי להפוך את הקינוח ל'טעם מיסו'",
    "descNew": "מיסו שירו (לבן) אורגני של Eden Foods, מותסס באיטיות בשיטה יפנית מסורתית. מיסו לבן קליל ומתקתק בהשוואה למיסו כהה, ומתאים היטב למרק, לרטבי סלט ולמריני דגים. Eden Foods מייצרת מיסו ביפן במטחנות מסורתיות.",
