    "longDesc": "פיתוח טכנולוגי המשלב את המרקם הפריך של נאצ'וס עם הקלילות של פופקורן. חטיפי PopCorners אינם מטוגנים אלא מיוצרים בתהליך של התפחה ואפייה (Popping) של גרעיני תירס, תהליך החוסך משמעותית בכמות השמן והקלוריות בהשוואה לצ'יפס רגיל. תיבול הצ'דר הלבן מעניק להם מליחות גבינתית עמוקה ועוטפת. פתרון מדויק לנשנוש מבוקר שאינו משאיר תחושת כבדות או ידיים שומניות. (כשרות OU חלבי).\n\nכדאי לדעת: לעומת צ'יפס תירס מטוגן, המרקם קל יותר ופחות שמנוני בפה; לעומת פופקורן אין קליפות וגרעינים, והטעם מתפזר באופן אחיד יותר על כל חתיכה.",
    "descNew": "צ'יפס תירס פופקורנס של PopCorners בטעם צ'דר לבן, מיוצרים מפופקורן מרוסק במקום מבצק תירס מטוגן. פחות שומן וטעם קרנצ'י יותר מצ'יפס רגיל, בלי גלוטן ובלי צבעים מלאכותיים. חטיף פופולרי בקרב שוחרי בריאות.",
