    "longDesc": "קמח אורז מלא הוא אורז מלא טחון, כולל שכבת הסובין והנבט. לכן צבעו חום-בהיר, טעמו אגוזי יותר וקיימים בו יותר סיבים מקמח אורז לבן, אך המרקם שלו גם מעט גרגירי יותר (כשרות Kehilla Kosher).\n\nלעומת קמח אורז לבן, הוא מוסיף טעם דגני, צבע כהה וסיבים, ולכן מתאים ללחמים מהירים, מאפינס ועוגיות כהות יותר. לעומת קמח חיטה מלא, הוא עדיין נטול גלוטן ואינו יכול להחליף קמח חיטה לבדו בלחם שמרים.\n\nרעיונות לשימוש:\n• להחליף עד רבע מכמות קמח החיטה במאפינס, פנקייקים או עוגיות לקבלת טעם אגוזי\n• לשלב בתערובת ללא גלוטן עם עמילן טפיוקה או ארורוט וחומר מקשר כמו קסנטן גאם\n• להשתמש כציפוי לקציצות, טופו או שניצל אפוי במקום פירורי לחם\n• להוסיף 2–3 כפות לבלילת לביבות ירק לספיגת נוזלים\n• להשתמש כרכיב בדייסת אורז או קרם אורז ביתי",
