    "longDesc": "כוסמת היא זרע של צמח ממשפחת הארכוביתיים, ולא דגן אמיתי למרות השם האנגלי Buckwheat. היא נמכרת כאן כגרעינים שלמים, עם טעם אגוזי ומעט אדמתי, ומתאימה לבישול כמו אורז או בורגול (כשרות Kehilla Kosher).\n\nלעומת בורגול, כוסמת טבעית נטולת גלוטן ואינה עשויה מחיטה. לעומת קינואה, היא בעלת טעם עמוק יותר ומרקם רך-נגיס, אך אינה מתאימה לכל מי שלא אוהב טעם דגני מודגש; חשוב לשטוף אותה לפני הבישול.\n\nרעיונות לשימוש:\n• לשטוף כוס כוסמת, לבשל עם 2 כוסות מים וקורט מלח, לכסות ולבשל 10–15 דקות עד לספיגת הנוזלים\n• להניח מכוסה 5 דקות ולאוורר במזלג לפני ההגשה\n• להשתמש במקום אורז או בורגול לצד תבשילים, ירקות צלויים או קציצות\n• לצנן ולערבב עם עשבי תיבול, מלפפון, עגבנייה, לימון ושמן זית לסלט כוסמת\n• לקלות במחבת יבשה 2–3 דקות לפני הבישול לקבלת טעם אגוזי מודגש יותר",
