    "longDesc": "דוחן הוא דגן זעיר ועגול בעל טעם עדין, מעט מתוק ואגוזי. הוא נפוץ במטבחים של אפריקה, הודו ואסיה, ומבושל יכול להיות או אוורירי כמו קוסקוס גס או רך וקרמי כמו דייסה, לפי יחס הנוזלים (כשרות Kehilla Kosher).\n\nלעומת קינואה, טעמו עדין יותר ואין בו המרירות הקלה האופיינית לחלק מסוגי הקינואה. לעומת אורז, הוא מתבשל מהר יחסית ונותן מרקם גרגרי; הוא נטול גלוטן, אך אינו בהכרח מוצר מתאים לצליאק אלא אם האריזה מציינת זאת במפורש.\n\nרעיונות לשימוש:\n• לקלות כוס דוחן במחבת יבשה 3–4 דקות לפני הבישול לטעם אגוזי יותר\n• לבשל כוס דוחן עם 2 כוסות מים וכפית מלח במשך 35–40 דקות כתוספת גרגרית\n• להשתמש ב-3 כוסות נוזל לכוס דוחן לקבלת מרקם רך יותר לדייסה או לקציצות\n• להחליף אורז בקערת ירקות, מוקפץ או תבשיל עדשים\n• לצנן דוחן מבושל ולשלב בסלט עם עשבי תיבול, ירקות קלויים ולימון\n• להשתמש בשאריות קרות להכנת קציצות עם ביצה או קמח חומוס לקשירה",
    "nameHe": "דוחן מלא ללא גלוטן",
