    "longDesc": "קמח סורגום מיוצר מדגן סורגום מלא, דגן עתיק בעל טעם עדין, מעט מתקתק ודומה במידת מה לקמח חיטה מלאה בהיר. הוא נטול גלוטן, צבעו בהיר יחסית, והוא נפוץ בתערובות אפייה ללא גלוטן משום שאינו משתלט בטעם (כשרות Kehilla Kosher).\n\nלעומת קמח אורז, הוא נותן יותר טעם דגני ופחות מרקם יבש-חולי. לעומת קמח חיטה, הוא אינו יוצר גלוטן ולכן צריך לשלבו עם עמילן וחומר מקשר באפייה; הוא אינו מתאים להחלפה מלאה בלחם שמרים ללא מתכון ייעודי.\n\nרעיונות לשימוש:\n• להשתמש בכ-30% מתערובת קמחים ללא גלוטן ללחם, עוגות או מאפינס\n• לשלב עם קמח אורז, טפיוקה וקסנטן גאם לקבלת תערובת אפייה מאוזנת יותר\n• להחליף עד רבע מקמח החיטה בפנקייקים או עוגיות לקבלת טעם דגני עדין\n• להוסיף 2 כפות לבלילת וופל או קרפים ללא גלוטן\n• לשמור בכלי אטום במקום קריר כדי לשמור על טריות הקמח המלא",
