    "cat": "תבלינים",
    "conf": "גבוהה",
    "brand": "The Spice Lab",
    "longDesc": "הקאלה נמאק (Kala Namak) הוא מלח סלעים וולקני שמקורו בהימלאיה. למרות שמו, צבעו נע בין סגול כהה לוורוד אפרפר כשהוא נטחן. הערך הקולינרי המרכזי שלו הוא נוכחות תרכובות גופרית טבעיות, המעניקות לו ארומה וטעם מובהקים של ביצה קשה. תכונה זו הופכת אותו ל\"נשק הסודי\" של המטבח הטבעוני – קורט ממנו בתערובת מקושקשת טופו, סלט תפוחי אדמה במיונז, או שקשוקה טבעונית, משחזר מיד את חוויית הטעם הביצתית החסרה. (כשרות OU).\n\nכדאי לדעת: לעומת מלח ים רגיל הוא לא רק מלוח — הארומה הגופריתית היא המאפיין המרכזי. לכן משתמשים בו בכמות קטנה במיוחד, ובעיקר במנות הודיות או טבעוניות שבהן רוצים אפקט של ביצה.\n\nטיפים לשימוש:\n• לטופו מקושקש: להתחיל ב־1/8 כפית ל־300 גרם טופו ולהוסיף רק אחרי טעימה\n• למיונז טבעוני: קורט קטן נותן תחושה של סלט ביצים\n• לצ'אט הודי או סלט פירות מתובל: קורט יחד עם כמון ולימון",
    "descNew": "מלח וולקני שחור-סגול מהודו שמשנה כללים במטבח הטבעוני. הגופרית הטבעית שבו יוצרת ריח וטעם של ביצה קשה, מה שהופך אותו למרכיב הסודי של טופו מקושקש, חביתות חומוס וסנדוויצ'ים טבעוניים שמרמים את החיך. ⚠️ חשוב: לא מלח ים רגיל. הריח גפריתי ואופייני, זה כוחו וזו מהותו. משתמשים בכמות זעירה בלבד. OU.",
