    "longDesc": "המוצר המקורי שהחל את שיגעון ה-Brownie Brittle בעולם הקונדיטוריה הנגישה. הפטנט פשוט וגאוני: דפי בראוניז דקיקים הנאפים עד לפריכות קיצונית, עמוסים בטעם קקאו אמיתי ומשובצים בנטיפי שוקולד קטנים. הם מספקים את החשק הבלתי נשלט לשוקולד, אך כיוון שהם דקים ואווריריים (בניגוד לבראוניז דחוס ועמוס חמאה וסוכר כבד), מנה גדולה מהם מכילה כמות קלוריות נמוכה משמעותית. מעבר לנשנוש נקי ישר מהשקית, הם נפלאים כשהם מרוסקים ומשמשים כבסיס קראנצ'י לפאי או תוספת פריכה מעל מוס שוקולד וגלידה. (כשרות OU).\n\nכדאי לדעת: לעומת בראוני רגיל אין כאן כמעט לחות או לעיסות; לעומת עוגיית שוקולד הוא בדרך כלל דק יותר ובעל טעם קקאו שמזכיר בראוני. זה מוצר למי שמעדיף קראנץ' על פני פאדג'.",
    "descNew": "הדבר הכי קרוב לבראוני בלי לאפות. Sheila G's לקחו את הקצוות הפריכים של הבראוני - החלק שכולם מתווכחים עליו - והפכו אותו למוצר שלם. דק כמו קרקר, פריך, עשיר בשוקולד. מגיע ב-4 טעמים: שבבי שוקולד, שוקולד מריר ומלח, קרמל מלוח וקראנץ' טופי. OU חלבי. 4,000+ נמכרים בחודש ב-iHerb - מוצר קאלט אמיתי.",
