    "longDesc": "ממתיק המיועד למי שמחפש 100% פרי נזיר טהור, ללא תוספת של סוכרים אלכוהוליים (כמו אריתריטול) המצויים ברוב התערובות בשוק. מכיוון שפרי הנזיר מתוק פי 300 מסוכר רגיל, האבקה הזו מרוכזת באופן קיצוני ודורשת שימוש בכמויות מזעריות (קצה כפית) כדי להמתיק קנקן שלם של משקה או מתכון שלם של עוגה. היא אינה משפיעה על רמות הסוכר בדם (אינדקס גליקמי 0), נמסה בקלות ואינה משאירה את טעם הלוואי המריר-מתכתי המזוהה עם סטיביה טהורה. (כשרות OU).\n\nכדאי לדעת: לעומת סוכר, תערובות מונק פרוט אינן מתקרמלות באותה צורה ועלולות להשאיר תחושת קירור קלה בפה.",
