    "desc": "תמצית איכותית המופקת ממיצוי של פולי וניל אמיתיים באלכוהול, ללא חומרי טעם סינתטיים או צבעי מאכל.  מתאימה במיוחד למנות שבהן הווניל הוא הכוכב ולקינוחים ללא אפייה (כמו קרם פטיסייר, קצפת או פנקוטה), שם הדקויות של הווניל הטבעי מורגשות היטב.\nמיוצרת ע\"י McCormick, אחד ממותגי התבלינים הוותיקים בעולם.",
    "longDesc": "תמצית וניל טהורה היא מיצוי של פולי וניל במים ובאלכוהול. היא אינה זהה ל\"טעם וניל\": המקור שלה הוא פולי וניל אמיתיים, ולכן הטעם מורכב, פרחוני-קרמלי ולעיתים מעט עצי (כשרות OU).\n\nלעומת תמצית וניל מלאכותית, תמצית טהורה נותנת עומק טבעי יותר אך בדרך כלל יקרה יותר. לעומת משחת וניל, היא אינה מוסיפה גרגרים שחורים ואינה מסמיכה את הבלילה; משחה עדיפה כשחשוב גם המראה, ותמצית נוחה יותר לשימוש יומיומי.\n\nרעיונות לשימוש:\n• להוסיף כפית אחת לבלילת עוגה בחושה או עוגיות בכמות של כ-20–24 יחידות\n• לערבב חצי כפית לתוך 250 מ״ל שמנת צמחית או קצפת לפני ההקצפה\n• להוסיף רבע כפית לדייסת שיבולת שועל של שתי מנות יחד עם קינמון וסילאן\n• לשלב כפית אחת בפנקייקים מ-1 כוס קמח כדי לעגל את טעם הביצים\n• להוסיף חצי כפית לסלט פירות של 4 מנות, במיוחד עם תותים, אפרסקים או מנגו\n• לערבב כפית אחת בבלילת פרנץ' טוסט מ-2 ביצים וחצי כוס חלב",
