    "longDesc": "טעם מייפל הוא חומר טעם נוזלי שנועד להעניק ארומת מייפל בלי להוסיף את כמות הסוכר, הסמיכות והמחיר של סירופ מייפל אמיתי. בגרסה זו הטעם מגיע משילוב של סירופ מייפל, מולסה וחומרי טעם, והוא אינו תחליף תזונתי לסירופ מייפל (כשרות KSA).\n\nלעומת סירופ מייפל, טעם מייפל נותן ארומה מרוכזת אך כמעט אינו תורם מתיקות, לחות או צבע קרמלי למתכון. לכן באפייה משתמשים בו בנוסף לממתיק, ולא במקום סירופ מייפל אלא אם המתכון כבר כולל סוכר או נוזלים אחרים.\n\nרעיונות לשימוש:\n• להוסיף חצי כפית לבלילת 12 מאפינס יחד עם סוכר חום או סוכר קוקוס\n• לערבב רבע כפית לתוך כוס אחת של שיבולת שועל חמה עם אגוזי פקאן וקינמון\n• להוסיף חצי כפית ל-250 מ״ל קצפת צמחית או קרם קוקוס מוקצף\n• לשלב רבע כפית בבלילת פנקייקים מ-1 כוס קמח, לצד כף סילאן או מייפל אמיתי\n• לערבב 3–4 טיפות בתוך 2 כפות חמאה או מרגרינה מומסת להברשת בטטה אפויה\n• להוסיף רבע כפית לשייק בננה-פקאן של שתי כוסות במקום להעמיס סירופ",
