    "longDesc": "טעם לימון אורגני הוא תערובת מרוכזת של שמן לימון ושמן חמניות, שנועדה להוסיף ארומת קליפת לימון בלי להוסיף נוזלים או חמיצות משמעותית. הוא שימושי במיוחד כשמבקשים טעם לימוני נקי בלי לגרר קליפה טרייה (כשרות KSA).\n\nלעומת מיץ לימון, הוא מעניק ריח וטעם של הקליפה אך כמעט אינו מחמיץ את המנה; לכן אינו יכול להחליף מיץ במתכון שזקוק לחומצה. לעומת גרידת לימון, הוא זמין כל השנה ואחיד בעוצמה, אך חסרים בו הסיבים והמראה של קליפה טרייה.\n\nרעיונות לשימוש:\n• להוסיף חצי כפית לבלילת עוגת לימון בתבנית אינגליש קייק, יחד עם מיץ וגרידת לימון אם המתכון כולל אותם\n• לערבב רבע כפית לתוך 250 מ״ל יוגורט או יוגורט צמחי עם דבש ופירות יער\n• להוסיף 3–4 טיפות לציפוי אבקת סוכר של כוס אחת אבקה ו-2 כפות נוזל\n• לשלב רבע כפית בבלילת 12 מאפינס פרג ולימון\n• להוסיף 2–3 טיפות לשייק תות-בננה של שתי כוסות לקבלת ניחוח הדרי\n• לערבב רבע כפית לתוך סורבה ביתי מ-500 גרם פירות קפואים",
