    "longDesc": "טעם תפוז אורגני הוא חומר טעם מרוכז המבוסס על שמן תפוז ושמן חמניות. הוא מדגיש את הארומה השמנית והמתוקה של קליפת התפוז, בלי כמות המים והחמיצות שמיץ תפוזים מוסיף (כשרות KSA).\n\nלעומת מיץ תפוזים, הוא אינו מספק נוזלים, מתיקות או חומציות ולכן אינו תחליף ישיר באפייה. לעומת גרידת תפוז טרייה, הוא נוח כשאין תפוז בבית ומאפשר לשלוט בעוצמה, אך לא יוסיף את חתיכות הקליפה או המרקם שלהן.\n\nרעיונות לשימוש:\n• להוסיף חצי כפית לבלילת עוגת שוקולד בתבנית אינגליש קייק לקבלת שילוב שוקולד-תפוז\n• לערבב רבע כפית לתוך 250 מ״ל יוגורט או יוגורט צמחי עם וניל ושקדים קצוצים\n• להוסיף 3–4 טיפות לגנאש שוקולד מ-200 גרם שוקולד מריר לקבלת טראפלס בטעם תפוז\n• לשלב רבע כפית בבלילת 12 מאפינס עם חמוציות או שוקולד צ'יפס\n• להוסיף 2–3 טיפות לשייק גזר, מנגו ובננה של שתי כוסות\n• לערבב רבע כפית לתוך ציפוי של כוס אבקת סוכר לעוגיות או עוגת תפוזים",
